get_role_slot() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f1
}

get_role_policy() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f2
}

get_role_priority() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f3
}

get_role_nice() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f4
}

# Launch profiles (issue #350): the second layout axis. The tier says
# where every role sits, the profile says which roles run at all. Every
# profile-aware helper takes it as $2 and defaults to the profile below,
# so a profile-unaware caller keeps the historical layout verbatim.
rtc_layout_profiles() {
  echo "mpc_on mpc_off"
}

rtc_default_profile() {
  echo "mpc_on"
}

# Non-zero for a profile id this layout does not declare. Callers that
# accept a profile from a CLI flag or a marker file validate here first --
# the per-tier lookups below reject it too, but "get_rt_cores returned
# nothing" is a much worse diagnostic than "unknown profile".
rtc_is_layout_profile() {
  local candidate="$1" known
  for known in $(rtc_layout_profiles); do
    [[ "$candidate" == "$known" ]] && return 0
  done
  return 1
}

# MPC slots as CSV. $1 overrides the detected
# physical core count so print_thread_layout and the tests can render a
# tier this machine does not have; $2 selects the launch profile, and a
# profile that drops MPC yields an empty list on every tier.
get_mpc_cores() {
  local ncpu="${1:-$(get_physical_cores)}"
  local profile="${2:-mpc_on}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier|$profile" in
    "4|mpc_on") echo "3" ;;
    "4|mpc_off") echo "" ;;
    "6|mpc_on") echo "3" ;;
    "6|mpc_off") echo "" ;;
    "8|mpc_on") echo "3" ;;
    "8|mpc_off") echo "" ;;
    "10|mpc_on") echo "3" ;;
    "10|mpc_off") echo "" ;;
    "12|mpc_on") echo "3" ;;
    "12|mpc_off") echo "" ;;
    "14|mpc_on") echo "3" ;;
    "14|mpc_off") echo "" ;;
    "16|mpc_on") echo "3" ;;
    "16|mpc_off") echo "" ;;
    *) return 1 ;;
  esac
}

# RT group slots: rt_control + rt_callback + MPC.
# Base for get_rt_cores_with_siblings() / get_cm_shield_cpus().
# 
# $2 (launch profile) is what shrinks the cset shield when MPC is off.
# get_rt_cores_with_siblings() deliberately does NOT forward it: that
# path feeds GRUB nohz_full / rcu_nocbs, which are boot-static and must
# stay the widest set so a profile switch never needs a reboot.
get_rt_cores() {
  local ncpu="${1:-$(get_physical_cores)}"
  local profile="${2:-mpc_on}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier|$profile" in
    "4|mpc_on") echo "1,2,3" ;;
    "4|mpc_off") echo "1,2" ;;
    "6|mpc_on") echo "1,2,3" ;;
    "6|mpc_off") echo "1,2" ;;
    "8|mpc_on") echo "1,2,3" ;;
    "8|mpc_off") echo "1,2" ;;
    "10|mpc_on") echo "1,2,3" ;;
    "10|mpc_off") echo "1,2" ;;
    "12|mpc_on") echo "1,2,3" ;;
    "12|mpc_off") echo "1,2" ;;
    "14|mpc_on") echo "1,2,3" ;;
    "14|mpc_off") echo "1,2" ;;
    "16|mpc_on") echo "1,2,3" ;;
    "16|mpc_off") echo "1,2" ;;
    *) return 1 ;;
  esac
}

# nrt_logging + nrt_callback + nrt_publish slots, deduplicated and
# ascending. Layout v5 folds all three onto the rt_callback slot, so
# this is a subset of get_rt_cores() on tiers >= 6; on the degraded
# tier they share the OS slot instead. Either way callers that shield
# must drop the OS slot (get_cm_shield_cpus does), never widen onto it.
get_nrt_cores() {
  local ncpu="${1:-$(get_physical_cores)}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier" in
    4) echo "0" ;;
    6) echo "2" ;;
    8) echo "2" ;;
    10) echo "2" ;;
    12) echo "2" ;;
    14) echo "2" ;;
    16) echo "2" ;;
  esac
}

